// Halo 3: what the runtime asks of the game (runtime/game.h). Generated by tools/slot.py:
// everything here is a default, to be replaced as the boot test (tools/boot_test.py) shows the need.
#include <stdafx.h>
#include <game.h>
#include <kernel/function.h>
#include <kernel/memory.h>
#include <os/logger.h>

// Waves' audio DLLs, recompiled (tools/slot_dlls.py): their function tables and the WavesLibDLL.dll
// imports of L360.dll and Q10.dll.
#include "dlls/modules.inc"

namespace game
{
    const char* Title()
    {
        return "Halo 3";
    }

    static size_t s_titleDllFunctions;

    void RegisterExtraFunctions(Memory& memory)
    {
        // The Waves DLLs' functions, at their load addresses (0x88000000-0x8B970000): the runtime
        // loader maps a DLL whose entry point is here (runtime/loader.cpp, XexLoadImage).
        // Runs from g_memory's constructor, before the logger exists: no LOGF here.
        for (const XportTitleDll& dll : kTitleDlls)
        {
            for (const PPCFuncMapping* f = dll.functions; f->guest != 0; f++)
            {
                if (f->host != nullptr)
                {
                    memory.InsertFunction(uint32_t(f->guest), f->host);
                    s_titleDllFunctions++;
                }
            }
        }
    }

    const char* ThreadName(uint32_t startAddress, uint32_t startContext, uint32_t& entry)
    {
        // The engine's render, audio and streaming threads, by entry point, to keep them on the
        // big cores (os/thread_policy.cpp). None known yet. The audio processor threads
        // (0x826C7228, 0x826C72F0; 13-16 % of a core each with the barrier below) stay unnamed: as
        // XpSoundThread (Role::Audio, nice -12) every wakeup would preempt XpRecorder (nice -10),
        // the thread that limits the frame rate. Not measured that way; no audio problem known.
        (void)startAddress;
        (void)startContext;
        (void)entry;
        return nullptr;
    }

    void AfterImageLoad()
    {
        LOGF("{} functions of {} title DLLs registered", s_titleDllFunctions, std::size(kTitleDlls));
    }

    const char* RendererOptions()
    {
        return "";
    }

    bool PauseMenuOpen()
    {
        return false;
    }
}

// ---- XAPI fibers (runtime/cpu/guest_fiber.h) --------------------------------------------------
// Halo 3 runs coroutines on fibers (sub_82317388: ConvertThreadToFiber once, then CreateFiber with
// a 32 KB stack and start 0x823169F8). Its statically linked XAPI keeps building and freeing the
// 2640-byte fiber blocks; the switch itself, which loads another fiber's r1 and LR, cannot run as
// recompiled code and goes to host fibers. Block layout (XAPI): +0 parameter, +4/+8/+12 stack
// allocation/base/limit, +28 LR, +48 r1, +152..+288 r14-r31; TEB+356 is the current fiber.
#include <cpu/guest_fiber.h>

extern "C" PPC_FUNC(__imp__sub_8259FC20); // ConvertThreadToFiber(parameter)
extern "C" PPC_FUNC(__imp__sub_8259FCB0); // ConvertFiberToThread()
extern "C" PPC_FUNC(__imp__sub_8259FD00); // CreateFiber(stackSize, start, parameter)
extern "C" PPC_FUNC(__imp__sub_8259FDE0); // DeleteFiber(fiber)
PPC_EXTERN_FUNC(sub_8259FE50);            // the start thunk's body: r3 = start, start(parameter)

PPC_FUNC(sub_8259FC20)
{
    __imp__sub_8259FC20(ctx, base);
    if (ctx.r3.u32 != 0)
        GuestFiberConvertThread(ctx, ctx.r3.u32);
}

PPC_FUNC(sub_8259FCB0)
{
    const uint32_t thread = PPC_LOAD_U32(ctx.r13.u32 + 256);
    const uint32_t fiber = PPC_LOAD_U32(thread + 356);
    if (fiber != 0)
        GuestFiberDelete(fiber);
    __imp__sub_8259FCB0(ctx, base);
}

PPC_FUNC(sub_8259FD00)
{
    __imp__sub_8259FD00(ctx, base);
    const uint32_t fiber = ctx.r3.u32;
    // The console's first switch "returns" into the start thunk 0x825A2170 (+28) with r1 = +48
    // and r31 = +288 (the start routine), which calls sub_8259FE50(start).
    if (fiber != 0)
        GuestFiberCreate(fiber, sub_8259FE50, uint32_t(PPC_LOAD_U64(fiber + 48)),
            uint32_t(PPC_LOAD_U64(fiber + 288)));
}

PPC_FUNC(sub_8259FDE0)
{
    GuestFiberDelete(ctx.r3.u32);
    __imp__sub_8259FDE0(ctx, base);
}

// SwitchToFiber(target) (sub_8259FE40 tail-calls it).
PPC_FUNC(sub_825A2180)
{
    const uint32_t target = ctx.r3.u32;
    const uint32_t thread = PPC_LOAD_U32(ctx.r13.u32 + 256);
    PPC_STORE_U32(thread + 356, target);
    // What KeSetCurrentStackPointers records: the KTHREAD's stack allocation, base and limit.
    PPC_STORE_U32(thread + 208, PPC_LOAD_U32(target + 4));
    PPC_STORE_U32(thread + 92, PPC_LOAD_U32(target + 8));
    PPC_STORE_U32(thread + 96, PPC_LOAD_U32(target + 12));
    GuestFiberSwitch(ctx, target);
}

// ---- Mesh command buffer cache -----------------------------------------------------------------
// Halo 3 records a mesh part's draws once into a D3D command buffer (cache at 0x830F5D70:
// sub_82458438 records, sub_82171968 replays it with RunCommandList) and from then on only
// replays it, about 10,000 times a second in a mission. The native renderer sees the D3D calls,
// not the GPU command lists, so it saw those draws only in the recording frame: the level's
// structure and objects vanished after it (black world, only decorators drawn, no lighting pass).
// sub_82171508 is that cache path (1 = drawn); 0 makes sub_821713F0 draw directly (sub_82174580).
PPC_FUNC(sub_82171508)
{
    ctx.r3.u64 = 0;
}

// ---- memcpy --------------------------------------------------------------------------------------
// The title's two memcpy (r3 destination, r4 source, r5 bytes; r3 is returned): sub_8258E090 (the
// CRT's, 1471 callers) and sub_82142338 (large copies: aligns the destination to 128, then
// sub_825A18C0 / sub_825A1C50 copy 128-byte lines with dcbz and VMX loads). Recompiled, every
// 16-byte vector store of those is a 16-iteration byte loop: sub_825A18C0 alone was 4.7% of the
// mission profile's samples, on MAIN_THREAD (simpleperf, 2026-11-07). The bytes are the same
// either way, so the host copies them; overlapping ranges keep the guest's forward copy.
extern "C" PPC_FUNC(__imp__sub_8258E090);
extern "C" PPC_FUNC(__imp__sub_82142338);

static bool HostGuestCopy(PPCContext& ctx, uint8_t* base)
{
    const uint32_t destination = ctx.r3.u32;
    const uint32_t source = ctx.r4.u32;
    const uint32_t bytes = ctx.r5.u32;
    if (bytes == 0)
        return true;
    const uint64_t destination_end = uint64_t(destination) + bytes;
    const uint64_t source_end = uint64_t(source) + bytes;
    if (destination_end > 0x100000000ull || source_end > 0x100000000ull)
        return false;
    if (destination < source_end && source < destination_end)
        return false;
    std::memcpy(base + destination, base + source, bytes);
    return true;
}

PPC_FUNC(sub_8258E090)
{
    if (!HostGuestCopy(ctx, base))
        __imp__sub_8258E090(ctx, base);
}

PPC_FUNC(sub_82142338)
{
    if (!HostGuestCopy(ctx, base))
        __imp__sub_82142338(ctx, base);
}

// ---- Utility drive (the hard disk's cache partitions) ------------------------------------------
// At boot sub_821984D8 mounts the utility drive with the statically linked XAPI's
// XMountUtilityDriveEx (sub_82582158(flags, 0x10000, 0xFF000)): it reads the console-signed "Josh"
// sector of \Device\Harddisk0\Partition0 (offset 0x800), formats the title's cache slot as FATX
// through \Device\Harddisk0\Cache<n>, then mounts it from a XAM task (sub_82581AD0) that stays
// to serve flushes. If that and a test file (cache0:\test.dat) work, it sets the byte at
// 0x828A1EAD, and only then do the campaign saves live on the disk: sub_8219AA48 creates
// cache1:\savegame0.bin and savegame1.bin (sub_821D6308); without it the save state is a block
// of memory. Here the raw-disk read already failed (the device is a host folder), the byte stayed
// 0 and a "save and quit" was gone when the app closed (2026-11-09). cache0: and cache1: are host
// folders in this runtime (kernel/io/nt_file.cpp), so the drive is reported as mounted. Only these
// three functions use the mount state (0x827C88AC).
PPC_FUNC(sub_82582158) // XMountUtilityDriveEx: 0 = mounted
{
    LOGFN("utility drive: mounted (flags 0x{:X}; cache0:/cache1: are the save folder's cache0/cache1)", ctx.r3.u32);
    ctx.r3.u64 = 0;
}

PPC_FUNC(sub_82581930) // XFlushUtilityDrive: each write is on the host disk already
{
    ctx.r3.u64 = 0;
}

PPC_FUNC(sub_825821A8) // XUnmountUtilityDrive
{
    ctx.r3.u64 = 0;
}

// ---- Audio processor barrier -------------------------------------------------------------------
// sub_826C61C8(object r3, flags r4): the audio engine's barrier between its processor threads.
// The caller's processor (byte at r13+268) sets its byte of the doubleword at r4; the processors
// that take part are the words at r3+308..+328 (processor 0..5, byte 0..5 of the doubleword, big-
// endian). The thread that finds them all set clears the doubleword; the others see zero and go.
// The console spins with db16cyc (lowers the hardware thread's priority): recompiled, the spin is
// a plain loop that held ~0.4 of a core in the mission profile (simpleperf, 2026-11-07) and keeps
// the late processor, a host thread like any other, off the core it needs. Same logic; the wait
// spins a little, then yields the core, then sleeps briefly.
#include <chrono>
#include <thread>

PPC_FUNC(sub_826C61C8)
{
    const uint32_t object = ctx.r3.u32;
    const uint32_t flags = ctx.r4.u32;
    if (PPC_LOAD_U32(object + 304) == 0)
        return;
    PPC_STORE_U8(flags + PPC_LOAD_U8(ctx.r13.u32 + 268), 1);
    uint64_t mask = 0;
    for (uint32_t processor = 0; processor < 6; processor++)
    {
        if (PPC_LOAD_U32(object + 308 + processor * 4) != 0)
            mask |= uint64_t(1) << (56 - processor * 8);
    }
    for (uint32_t spins = 0;; spins++)
    {
        const uint64_t value = PPC_LOAD_U64(flags);
        if (value == 0)
            return;
        if (value == mask)
        {
            PPC_STORE_U64(flags, 0);
            return;
        }
        if (spins < 64)
        {
#if defined(__aarch64__)
            asm volatile("yield" ::: "memory");
#elif defined(__x86_64__) || defined(_M_X64)
            __builtin_ia32_pause();
#endif
        }
        else if (spins < 64 + 256)
        {
            std::this_thread::yield();
        }
        else
        {
            std::this_thread::sleep_for(std::chrono::microseconds(20));
        }
    }
}
